def write_csv(name, fields, rows):
    with (OUT / name).open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader(); w.writerows(rows)

def sha256(path):
    h = hashlib.sha256()
    with path.open("rb") as f:
        for b in iter(lambda: f.read(1024 * 1024), b""): h.update(b)
    return h.hexdigest()

def main():
    OUT.mkdir(parents=True, exist_ok=True)
    write_csv("source_qualification_ledger.csv", FIELDS, SOURCES)
    write_csv("license_audit.csv", ["source_id","license_status","license_evidence","file_level_rights","attribution","decision"], [
        {"source_id":s["source_id"],"license_status":s["license"],"license_evidence":s["license_evidence_url"],"file_level_rights":s["third_party_ancestry"],"attribution":s["attribution_requirements"],"decision":s["qualification_status"]} for s in SOURCES])
    write_csv("provenance_audit.csv", ["source_id","recording_id","session_id","device_id","grouping_method","ancestry","overlap","decision"], [
        {"source_id":s["source_id"],"recording_id":s["recording_id_available"],"session_id":s["session_id_available"],"device_id":s["device_id_available"],"grouping_method":s["source_grouping_method"],"ancestry":s["third_party_ancestry"],"overlap":s["known_dataset_overlap"],"decision":s["qualification_status"]} for s in SOURCES])
    write_csv("label_quality_audit.csv", ["source_id","labels","timestamps","verified_background","label_risk","decision"], [
        {"source_id":s["source_id"],"labels":s["label_types"],"timestamps":s["event_timestamps_available"],"verified_background":s["verified_background_available"],"label_risk":s["decision_reason"],"decision":s["qualification_status"]} for s in SOURCES])
    score_rows=[]
    score_map={
        "fsd50k_zenodo_5117901":(2,2,2,1,1,1,1,"Good Freesound IDs and clip labels, but mixed rights, no sessions, no verified background, and a multi-GB archive."),
        "arca23k_zenodo_5117901":(1,2,0,1,1,1,1,"Per-source IDs exist, but the official record reports substantial automated label error and no exact chainsaw/background coverage."),
        "audioset_google":(1,3,2,1,3,3,1,"Strong video/timestamp grouping, but raw audio rights/access are not supplied by the official release."),
    }
    for s in SOURCES:
        vals=score_map.get(s["source_id"],(0,0,0,0,0,0,0,"Known source already audited or blocked; not a new acquisition candidate."))
        score_rows.append(dict(source_id=s["source_id"],dataset_name=s["dataset_name"],licensing_score=vals[0],recording_provenance_score=vals[1],label_quality_score=vals[2],environmental_relevance_score=vals[3],independent_coverage_score=vals[4],access_size_score=vals[5],overlap_risk_score=vals[6],total_score=sum(vals[:7]),rationale=vals[7],qualification_status=s["qualification_status"]))
    write_csv("candidate_ranking.csv", list(score_rows[0]), score_rows)
    # Required even when no source qualifies: a header-only manifest is an explicit no-download record.
    write_csv("acquisition_manifest.csv", ["source_id","downloaded","path","sha256","bytes","validation_status","eligibility_status"], [])
    write_csv("duplicate_and_ancestry_audit.csv", ["source_id","download_performed","exact_hash_status","decoded_hash_status","near_duplicate_status","ancestry_status","notes"], [])
    protected=json.loads(PROTECTED.read_text())
    frozen={p:sha256(Path(p)) for p in protected["frozen_hashes"]}
    matches={p:(v==protected["frozen_hashes"][p]) for p,v in frozen.items()}
    hashes={"audit_timestamp_utc":datetime.now(timezone.utc).isoformat(),"script":"run_source_first_discovery.py","python":platform.python_version(),"downloads_performed":0,"model_inference_started":False,"model_training_started":False,"threshold_tuning_started":False,"frozen_manifests_changed":False,"phase4_3_decisions_changed":False,"protected_frozen_hashes":frozen,"protected_hash_matches":matches,"all_protected_hashes_match":all(matches.values()),"source_count":len(SOURCES),"qualified_source_count":0,"qualification_status_counts":{}}
    for s in SOURCES: hashes["qualification_status_counts"][s["qualification_status"]]=hashes["qualification_status_counts"].get(s["qualification_status"],0)+1
    (OUT / "integrity_hashes.json").write_text(json.dumps(hashes,indent=2)+"\n")
    decision={"decision":"NO_QUALIFIED_SOURCE_NO_DOWNLOAD","audit_scope":"Phase 4.10 source-first discovery and admission gate","source_count":len(SOURCES),"qualified_for_download":[],"downloads_performed":0,"acquisition_manifest":"header-only; no source passed all three mandatory gates","blocked_sources":[s["source_id"] for s in SOURCES if s["qualification_status"]!="QUALIFIED_FOR_DOWNLOAD"],"next_action":"Do not download or admit data. Resolve file-level rights/provenance and labels only if new primary evidence becomes available.","frozen_artifacts_changed":False,"training_started":False,"model_inference_started":False,"phase5_started":False}
    (OUT / "source_qualification_decision.json").write_text(json.dumps(decision,indent=2)+"\n")
    report=f'''# Phase 4.10 — Source-First Dataset Discovery and Admission\n\nAudit date: {datetime.now(timezone.utc).date().isoformat()} (UTC)\n\n## Decision\n\n**NO QUALIFIED SOURCE — NO DOWNLOAD.** No investigated source passed all three mandatory gates: usable license, defensible original-recording/source grouping, and labels suitable for the requested class decision. The acquisition manifest is intentionally header-only.\n\nNo external audio was downloaded in this phase. No model inference, training, threshold tuning, preprocessing change, frozen-split change, Phase 4.3 decision change, or firmware change was performed.\n\n## Findings\n\n| Source | Status | Main blocker |\n|---|---|---|\n'''+"\n".join(f"| {s['dataset_name']} | {s['qualification_status']} | {s['decision_reason']} |" for s in SOURCES)+f'''\n\n### New candidates\n\n**FSD50K** is the strongest research lead, not an acquisition approval. The official records describe 51,197 Freesound clips with Freesound IDs and human-labeled AudioSet-ontology classes. However, audio has mixed per-clip CC rights, source/session/device grouping is not available, the labels are clip-level rather than event timestamps, verified background negatives are absent, and the full archive is multi-gigabyte with no selective official file-download path demonstrated. It remains **DEFERRED_LICENSE**.\n\n**ARCA23K/ARCA23K-FSD** has source URLs and an explicit gunshot/gunfire class, but the official record says ARCA23K was automatically created with no manual verification and estimates 46.4% of training examples are incorrectly labelled. It has no verified background class and no exact chainsaw class in the listed taxonomy. It remains **DEFERRED_LABELS**.\n\n**AudioSet** has the best metadata structure: YouTube video IDs, start/end seconds, and multi-label human annotations. The official release provides CSV metadata and precomputed features, not raw source audio. Retrieving raw audio would depend on third-party platform availability and rights outside the release; therefore it is not a lawful qualified audio acquisition path. It remains **DEFERRED_LICENSE**.\n\nPreviously investigated sources were not redownloaded. Kenya, IOAI, Vietnam, Rodopi, Sensing the Forest, Belize, Illinois, and Outdoor Gunfire retain their Phase 4.7–4.9 dispositions; no automatic admission or relabeling was performed.\n\n## Gate and ranking summary\n\nThe ranking rubric uses seven 0–3 criteria: licensing, recording-level provenance, label quality, environmental relevance, likely independent-recording coverage, accessibility/size, and overlap risk (higher is safer). Scores and evidence are in `candidate_ranking.csv`. No source reached `QUALIFIED_FOR_DOWNLOAD`.\n\n## Data and leakage risks\n\nNo new audio means no new hashes or near-duplicate comparisons were possible. Existing Phase 4.9 evidence remains authoritative for the staged IOAI/Vietnam material: 90 IOAI files matched local FSC22, Vietnam includes a mixed Belize branch and internal repeats, and no staged file was eligible. Any future source must be grouped by original recording/session before splitting; adjacent windows must not be treated as independent recordings.\n\n## Existing contract preserved\n\nThe frozen preprocessing contract remains 16 kHz mono, peak normalization to -3 dB, 1.0-second windows, 0.5-second hop, 40 mel bins, FFT 512, feature hop 160, power 2, and frozen feature mean/std. No new pipeline was proposed or executed.\n\n## Validation\n\n`run_source_first_discovery.py` recomputed all nine protected frozen hashes from `online_dataset_audit_checks.json`; `integrity_hashes.json` records the actual results. It also confirms zero downloads and zero model/training activity.\n\n## Primary evidence\n\n- [FSD50K/ARCA23K Zenodo record](https://zenodo.org/records/5117901)\n- [Freesound dataset index](https://labs.freesound.org/datasets/)\n- [AudioSet official download and license page](https://research.google.com/audioset/download.html)\n- [Phase 4.9 provenance report](../phase4_9_source_provenance/SOURCE_PROVENANCE_REPORT.md)\n- [Phase 4.8 acquisition report](../phase4_8_fasttrack_acquisition/ACQUISITION_REPORT.md)\n\n## Remaining action\n\nKeep all candidates quarantined. If the project wants to revisit FSD50K, first obtain an exact per-file permissive-license subset and a defensible source-group policy from its metadata; this is a new admission review, not a reason to download the full archive. Phase 5 remains blocked.\n'''
    (OUT / "SOURCE_FIRST_DISCOVERY_REPORT.md").write_text(report)
    print(json.dumps({"out":str(OUT),"sources":len(SOURCES),"qualified":0,"downloads":0,"protected_hashes_match":all(matches.values())},indent=2))

if __name__ == "__main__": main()
